// Extract question and source from webhook payload
const body = $input.first().json.body;
const query = body.question || body.message || body.text || '';
const source = body.source || 'web';
const userId = body.user_id || body.from?.id || 'anonymous';
const language = body.language || (query.toLowerCase().match(/\b(hola|gracias|precio|horario|cuanto|cuando)\b/) ? 'es' : 'es');

// Normalize the question
const normalizedQuestion = query.trim().toLowerCase();

return [{
  json: {
    original_question: query,
    normalized_question: normalizedQuestion,
    source: source,
    user_id: userId,
    language: language,
    timestamp: new Date().toISOString()
  }
}];

// Read RAG context from previous node
const ragData = $input.first().json;
const question = $('Parse Input').first().json.normalized_question;

// Simple keyword matching to find relevant RAG sections
// In production, use embeddings for semantic search
const ragContent = ragData.toString();

// Extract relevant sections based on keywords
const keywords = {
  'schedule': ['horario', 'schedule', 'clases', 'clase', 'hora', 'hora', 'manana', 'tarde', 'noche'],
  'price': ['precio', 'price', 'costo', 'cuanto', 'pago', 'mensual', 'mensualidad'],
  'level': ['nivel', 'level', 'basico', 'intermedio', 'avanzado', 'beginner', 'intermediate'],
  'inscription': ['inscripcion', 'enrollment', 'registro', 'registrar', 'matricula'],
  'certification': ['certificado', 'certification', 'certificado', 'examen', 'exams'],
  'modality': ['modalidad', 'modality', 'presencial', 'online', 'virtual', 'hibrido', 'self-paced']
};

let relevantContext = '';

// Match keywords to find relevant sections
for (const [topic, words] of Object.entries(keywords)) {
  if (words.some(w => question.includes(w))) {
    relevantContext += `\n[${topic.toUpperCase()} SECTION]\n`;
  }
}

// If no specific match, return general academy info
if (!relevantContext) {
  relevantContext = ragContent;
}

return [{
  json: {
    rag_context: ragContent,
    relevant_sections: relevantContext,
    question: question
  }
}];

