// Parse Gemini response
const geminiResponse = $input.first().json;
const questionData = $('Parse Input').first().json;

let aiResponse = '';

if (geminiResponse.candidates && geminiResponse.candidates[0]?.content?.parts[0]?.text) {
  aiResponse = geminiResponse.candidates[0].content.parts[0].text;
} else if (geminiResponse.error) {
  aiResponse = 'Lo siento, hubo un error al procesar tu pregunta. Por favor, intenta de nuevo o contacta a la academia directamente.';
} else {
  aiResponse = 'No pude generar una respuesta. Por favor, contacta a la academia para más información.';
}

return [{
  json: {
    response: aiResponse,
    source: questionData.source,
    user_id: questionData.user_id,
    original_question: questionData.original_question,
    language: questionData.language
  }
}];
